function validate([colors]) {
  if (!Array.isArray(colors) || colors.length < 2 || colors.length > 100) return 'colors needs 2 to 100 houses.';
  if (colors.some(c => !Number.isInteger(c) || c < 0 || c > 100)) return 'Each colour is an integer between 0 and 100.';
  if (colors.every(c => c === colors[0])) return 'At least two houses must have different colours.';
  return null;
}

