function maxDistance(colors) {
  const n = colors.length;
  let best = 0;

  for (let right = n - 1; right > 0; right--) {
    if (colors[right] !== colors[0]) {
      best = right;
      break;
    }
  }
  for (let left = 0; left < n - 1; left++) {
    if (colors[left] !== colors[n - 1]) {
      best = Math.max(best, n - 1 - left);
      break;
    }
  }
  return best;
}

