function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  for (;;) {
    const n = size === 'large' ? 100 : int(2, 8);
    const shape = int(0, 2);
    let colors;
    if (shape === 0) {
      // One colour everywhere except a single house somewhere.
      const base = int(0, 100);
      colors = Array(n).fill(base);
      colors[int(0, n - 1)] = (base + int(1, 100)) % 101;
    } else if (shape === 1) {
      const a = int(0, 100), b = int(0, 100);
      colors = Array.from({ length: n }, () => (rand() < 0.8 ? a : b));
    } else {
      const top = size === 'large' ? 100 : int(1, 3);
      colors = Array.from({ length: n }, () => int(0, top));
    }
    if (colors.some(c => c !== colors[0])) return [colors];
  }
}
